/**
 * emit to subscription queries of type FindInventoryItem,
 * but only if the id matches
 *
 * @param		entity	InventoryItem
 */
	protected void emitFindInventoryItem( InventoryItem entity ) {
		LOGGER.info("handling emitFindInventoryItem" );
		
	    queryUpdateEmitter.emit(FindInventoryItemQuery.class,
	                            query -> query.getFilter().getInventoryItemId().equals(entity.getInventoryItemId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllInventoryItem
	 * 
	 * @param		entity	InventoryItem
	 */
	protected void emitFindAllInventoryItem( InventoryItem entity ) {
		LOGGER.info("handling emitFindAllInventoryItem" );
		
	    queryUpdateEmitter.emit(FindAllInventoryItemQuery.class,
	                            query -> true,
	                            entity);
	}

